INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77675, 'spa', 'Arrancar espigas', 'Las tres apariciones describen la misma controversia en los evangelios sinópticos: Mateo 12:1, Marcos 2:23 y Lucas 6:1 narran cómo los discípulos arrancaban (τίλλω) espigas al pasar por los sembrados en sábado. Los fariseos lo cuestionaron como trabajo ilícito, lo que provocó la respuesta de Jesús sobre David comiendo los panes de la proposición y su declaración de que «el Hijo del Hombre es Señor del sábado».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77677, 'spa', 'Honrar, estimar o mostrar reverencia a una persona, especialmente a Dios o a los', 'Honrar, estimar o mostrar reverencia a una persona, especialmente a Dios o a los padres. Jesús cita el mandamiento del Decálogo «Honra a tu padre y a tu madre» (Mt 15:4; Mc 7:10) y condena a quienes «me honran con los labios» mientras su corazón está lejos (Mt 15:8; Mc 7:6). Esta acepción abarca la gran mayoría de las apariciones del verbo y expresa el reconocimiento de la dignidad inherente de alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77685, 'spa', 'Fijar un precio o asignar un valor monetario a alguien o algo', 'Fijar un precio o asignar un valor monetario a alguien o algo. Aparece solo en Mateo 27:9, donde se cumplen las palabras del profeta sobre «el precio del que fue valorado». Los líderes de Israel redujeron el valor del Mesías a treinta monedas de plata. Acepción poco frecuente pero teológicamente devastadora, al contrastar el honor infinito que merece Cristo con el precio de un esclavo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77688, 'spa', 'honor, estima, respeto', 'honor, estima, respeto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77689, 'spa', 'precio, valor monetario, producto de venta', 'precio, valor monetario, producto de venta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77696, 'spa', 'Precioso, costoso o de gran valor en un sentido material o intrínseco, describie', 'Precioso, costoso o de gran valor en un sentido material o intrínseco, describiendo objetos, sustancias o realidades que poseen alto valor. Esto cubre la mayoría de las apariciones en el NT: piedras preciosas y oro (1 Corintios 3:12, Apocalipsis 17:4, 18:12, 21:11), la ''preciosa sangre'' de Cristo como de un cordero sin mancha (1 Pedro 1:19), las ''preciosas y grandísimas promesas'' de Dios (2 Pedro 1:4), y el fruto precioso de la tierra (Santiago 5:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77698, 'spa', 'Honrado, estimado o tenido en alta consideración, describiendo personas o instit', 'Honrado, estimado o tenido en alta consideración, describiendo personas o instituciones dignas de respeto y posición social. En Hechos 5:34 Gamaliel es llamado τίμιος, ''honrado por todo el pueblo'', designando su reputación y autoridad más que cualquier valor material. Hebreos 13:4 declara el matrimonio τίμιος ''entre todos'', señalando dignidad moral y estima comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77701, 'spa', 'Nombre propio del colaborador más confiable y delegado de Pablo, del griego Τιμό', 'Nombre propio del colaborador más confiable y delegado de Pablo, del griego Τιμόθεος (''el que honra a Dios''). Reclutado en Listra siendo joven discípulo de madre judía y padre griego (Hch 16:1-3), se convirtió en el principal emisario de Pablo ante las iglesias en dificultades (1 Ts 3:2; 1 Co 4:17; Fil 2:19-23). Coautor de seis cartas paulinas y destinatario de dos epístolas pastorales con instrucciones para el liderazgo eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77708, 'spa', 'alguien, alguno (persona)', 'Pronombre indefinido sustantivo referido a una persona no especificada: ''alguien, alguno, cierta persona'' — 217 ocurrencias. Es el uso pronominal nuclear donde τις funciona solo como sujeto u objeto significando ''alguien.'' En Mateo 16:24 ''si alguno quiere venir en pos de mí,'' la indefinitud crea una invitación abierta; en Mateo 12:29 ''¿cómo puede alguno entrar en la casa del hombre fuerte?,'' plantea un desafío retórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77709, 'spa', 'algo (cosa)', 'Pronombre indefinido sustantivo referido a una cosa no especificada: ''algo, alguna cosa'' — 89 ocurrencias donde el neutro τι significa ''alguna cosa'' y no ''alguna persona.'' En Mateo 5:23 ''si... recuerdas que tu hermano tiene algo contra ti,'' y Marcos 8:23 Jesús pregunta al ciego ''¿ves algo?'' El español ''algo'' selecciona una forma dedicada para cosas, resolviendo la ambigüedad de género que el griego τις deja abierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77710, 'spa', 'algunos, ciertos (plural)', 'Pronombre indefinido plural: ''algunos, ciertos, algunos de ellos'' — 122 ocurrencias donde τινες se refiere a un subgrupo no especificado dentro de un conjunto mayor. En Mateo 9:3 ''algunos de los escribas dijeron,'' Mateo 16:28 ''algunos de los que están aquí'' y Mateo 28:11 ''algunos de la guardia'' — la palabra selecciona un subconjunto sin identificar individuos. El español ''algunos'' funciona como equivalente dedicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77711, 'spa', 'cierto, un (modificador)', 'Uso adjetival o determinante que modifica un sustantivo: ''cierto, algún'' — 99 ocurrencias donde τις no funciona como pronombre independiente sino como adjetivo que introduce un referente específico pero innominado. Las introducciones parabólicas lucanas son los ejemplos clásicos: ''cierto sacerdote'' (Lucas 10:31), ''cierto hombre'' (Lucas 15:11), ''cierto hombre rico'' (Lucas 16:1). El español ''cierto'' captura precisamente esta función.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77742, 'spa', '¿quién? (límite interrogativo)', 'Una única ocurrencia en Lucas 8:45 donde Jesús pregunta ''¿Quién me ha tocado?'' — aquí la tradición manuscrita y el contexto sugieren que τις puede funcionar en la frontera entre lo indefinido (''alguien me tocó'') y lo interrogativo (''¿quién me tocó?''). La forma enclítica indica que la respuesta de Pedro parafrasea la constatación de Jesús de que ''alguien'' lo tocó, mientras que las glosas lo tratan como interrogativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77760, 'spa', 'qué / cuál (cosas)', 'Pronombre interrogativo que pregunta por la identidad, naturaleza o selección de una cosa, evento o concepto: ''¿qué?'', ''¿cuál?'', ''¿qué clase de?'' Es el uso más frecuente (327 ocurrencias). Jesús pregunta τί ποιήσει ὁ κύριος (''¿qué hará el señor?'') y τί ὑμῖν δοκεῖ (''¿qué os parece?''). El español ''qué'' capta con precisión esta interrogación orientada a cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77761, 'spa', 'quién (personas)', 'Pronombre interrogativo que pregunta por la identidad de una persona: ''¿quién?'', ''¿a quién?'', ''¿de quién?'' (170 ocurrencias). En Mt 3:7, τίς ὑπέδειξεν ὑμῖν — ''¿quién os advirtió que huyerais?'' El español ''quién'' marca claramente la pregunta dirigida a personas, distinción que el griego expresa mediante la flexión casual y no con un lexema distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77763, 'spa', 'por qué (causal)', 'Interrogativo causal que significa ''¿por qué?'', ''¿para qué?'', ''¿con qué fin?'' (69 ocurrencias), generalmente como τί o διὰ τί en construcciones preposicionales. En Mt 8:26, Jesús pregunta a los discípulos τί δειλοί ἐστε — ''¿por qué teméis?'' El español desglosa este sentido en ''por qué'' (causa) y ''para qué'' (propósito), revelando un matiz que el griego deja abierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77777, 'spa', 'alguien o algo (indefinido)', 'Pronombre indefinido poco frecuente que significa ''alguien'', ''algo'', ''cualquier cosa'' (4 ocurrencias). En Mc 4:22, οὐ γάρ ἐστίν τι κρυπτόν — ''pues no hay nada oculto.'' El español ''algo'' y ''alguno'' captan el desplazamiento de la fuerza interrogativa a la indefinida. Este uso, más habitual en el griego clásico, aparece esporádicamente en el Nuevo Testamento cuando el contexto suprime la intención de pregunta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77790, 'spa', 'Tito (compañero de Pablo) -- Nombre propio Tito (griego Τίτος), colaborador gent', 'Tito (compañero de Pablo) -- Nombre propio Tito (griego Τίτος), colaborador gentil de Pablo a quien llama ''verdadero hijo en la fe común'' (Tit 1:4). Tito sirvió como delegado de Pablo en Corinto durante la crisis de la colecta (2 Co 8:6, 16, 23) y posteriormente supervisó las iglesias de Creta. El nombre se translitera de forma consistente en todos los idiomas, confirmando una referencia estable como nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77792, 'spa', 'Ticio (variante de nombre propio) -- Variante del nombre propio Ticio (griego Τί', 'Ticio (variante de nombre propio) -- Variante del nombre propio Ticio (griego Τίτιος), que aparece únicamente en Hch 18:7 en ciertas tradiciones manuscritas. Se refiere a Ticio Justo, un temeroso de Dios en Corinto cuya casa estaba junto a la sinagoga. La variación textual se refleja en la diversidad de traducciones: algunos idiomas lo traducen igual que el sentido 1, mientras otros preservan la grafía distinta, sugiriendo un personaje diferente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77794, 'spa', 'Conclusión inferencial', 'Las tres apariciones muestran funciones retóricas variadas: Lucas 20:25 concluye la enseñanza de Jesús sobre el tributo: «Dad, pues (τοίνυν), al César lo que es del César». 1 Corintios 9:26 aplica la metáfora atlética de Pablo: «Así pues (τοίνυν), yo corro sin vagar». Hebreos 13:13 extrae una consecuencia: «Salgamos, pues (τοίνυν), a él fuera del campamento».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77796, 'spa', 'Tal persona, tales', 'Uso sustantivado referido a una persona o personas de cierto carácter descrito: ''tal'', ''tales''. Jesús declara que el reino pertenece a ''los que son como estos'' (Mt 19:14; Mc 9:37), señalando una categoría definida por cualidades infantiles. Pablo se refiere igualmente a ''tales'' que practican ciertas conductas (Gá 6:1; 2 Ts 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77797, 'spa', 'De tal clase', 'Uso adjetival o calificativo que describe la naturaleza, clase o cualidad de algo: ''tal poder'', ''tal cosa''. Cuando las multitudes ven las sanaciones de Jesús, se maravillan de que ''tal autoridad'' fuera dada a los hombres (Mt 9:8). Marcos lo emplea para describir aflicciones ''como'' no las ha habido desde la creación (Mc 13:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77799, 'spa', 'Tales cosas', 'Uso sustantivado referido a cosas, asuntos o realidades abstractas de cierta clase: ''tales cosas'', ''tales asuntos''. Pablo emplea este sentido en argumentación moral: los que practican ''tales cosas'' merecen juicio (Ro 1:32; 2:2-3). Lucas lo utiliza cuando Herodes se pregunta por ''tales cosas'' que oye acerca de Jesús (Lc 9:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77819, 'spa', 'Aventurarse o atreverse a realizar una acción específica, implicando que la acci', 'Aventurarse o atreverse a realizar una acción específica, implicando que la acción requiere audacia porque otros vacilarían o se negarían. La construcción típicamente lleva un infinitivo complemento: los fariseos «ya no se atrevían a preguntarle nada» (Mt 22:46; Lc 20:40), y los discípulos «no se atrevían a preguntarle» al Señor resucitado quién era (Jn 21:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77823, 'spa', 'Mostrar audacia o valentía como disposición interior más que hacia una acción es', 'Mostrar audacia o valentía como disposición interior más que hacia una acción específica. José de Arimatea, «habiendo cobrado ánimo» (τολμήσας), fue a Pilato (Mc 15:43), donde el participio describe su estado de corazón. El uso de Pablo en 2 Cor 11:21 enmarca igualmente la osadía como cualidad de carácter.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77836, 'spa', 'Lugar, ubicación', 'Ubicación física, sitio, región o área designada, cubriendo desde sitios específicos hasta espacios generales. En los Evangelios, τόπος identifica localidades del paisaje narrativo: lugares desiertos (Mt 14:13), lugares santos (Mt 24:15) y localidades nombradas (Mt 27:33). El uso epistolar se extiende hacia la ''oportunidad'' abstracta, como no dar lugar al diablo (Ef 4:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77839, 'spa', 'Tanto, en tal grado', 'Tanto, en tal grado: cuantificando algo incontable o abstracto, frecuentemente en construcciones correlativas. Ananías vende un terreno «por tanto» (Hch 5:8); Cristo es superior «en tanto más» cuanto su nombre supera al de los ángeles (Heb 1:4; 7:22). Las estructuras comparativas repetidas marcan grado más que conteo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77840, 'spa', 'Tan grande, de tal magnitud', 'Tan grande, de tal magnitud: enfatizando el tamaño o la cualidad impresionante de algo. La fe del centurión es «tan grande» que Jesús se maravilla (Mt 8:10; cf. Lc 7:9); la nube de testigos es «tan grande» (Heb 12:1); las riquezas de Babilonia son destruidas en una hora: «tan grande» riqueza asolada (Ap 18:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77842, 'spa', 'Tantos', 'Tantos: referido a una pluralidad contable cuyo número impresionante se destaca. Jesús se asombra de que tantos panes no puedan alimentar a la multitud (Mt 15:33); el hijo mayor protesta que sirvió tantos años (Lc 15:29); a pesar de tantas señales, la multitud no creyó (Jn 12:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77852, 'spa', 'entonces', 'Adverbio temporal que significa ''en aquel momento'' o ''entonces'', empleado 160 veces para señalar la progresión secuencial en la narrativa o introducir el siguiente evento de una cadena. Especialmente prominente en el Evangelio de Mateo como nexo estructural (Mt 2:7; 3:13; 4:1), τότε enlaza episodios e indica consecuencia lógica. Todas las lenguas estudiadas lo traducen con un adverbio temporal directo — español ''entonces'', francés ''alors''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77854, 'spa', 'Inversión adversativa', 'Cada aparición marca una inversión dramática: 2 Corintios 2:7 insta a los corintios a perdonar y consolar al pecador arrepentido, «al contrario» de excluirlo — gracia en lugar de castigo. Gálatas 2:7 muestra a Pedro y los líderes de Jerusalén reconociendo que a Pablo se le confió el evangelio para los incircuncisos, «por el contrario» a necesitar su autorización — igualdad apostólica inesperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77856, 'spa', 'Macho cabrío sacrificial', 'Macho cabrío destinado al uso sacrificial, especialmente en los rituales del Día de la Expiación. Las cuatro apariciones en el NT (Heb 9:12,13,19; 10:4) contrastan la sangre de estos animales con el sacrificio superior de Cristo. El término refleja el requisito levítico de víctimas masculinas y evoca todo el sistema sacrificial de la Antigua Alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77857, 'spa', 'Mesa (para comer/servir) -- Mesa usada para comidas, banquetes o cenas ceremonia', 'Mesa (para comer/servir) -- Mesa usada para comidas, banquetes o cenas ceremoniales: la superficie alrededor de la cual se desarrollan la hospitalidad, la comunión y las comidas sagradas. Abarca la mesa del Señor (1 Co 10:21), las mesas que Jesús volcó en el templo (Mt 21:12; Mr 11:15), y las mesas domésticas de las parábolas. La mujer sirofenicia ruega por las migajas que caen de la mesa del amo (Mt 15:27; Mr 7:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77859, 'spa', 'Mesa de cambista, banco -- Mesa de cambista que funciona como mostrador financie', 'Mesa de cambista, banco -- Mesa de cambista que funciona como mostrador financiero o banco. En Lc 19:23, el amo pregunta por qué el siervo no depositó el dinero ''en el banco'' (literalmente ''sobre la mesa''). El español pasa de ''mesa'' a ''banco'', revelando directamente el sentido comercial especializado. Este uso refleja la práctica antigua donde los banqueros realizaban transacciones en mesas públicas, origen etimológico de la palabra ''banco''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77864, 'spa', 'Cuello, garganta', 'El cuello o garganta — la parte anatómica frontal y lateral del cuello. Se usa literalmente pero en contextos altamente figurativos: una piedra de molino colgada al cuello como imagen de juicio catastrófico (Mt 18:6; Mr 9:42; Lc 17:2), el padre echándose al cuello del pródigo en abrazo gozoso (Lc 15:20), y el yugo metafórico puesto sobre el cuello de los conversos gentiles (Hch 15:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77867, 'spa', 'Tres', 'El numeral cardinal tres, usado para el conteo literal y para agrupaciones teológicamente significativas a lo largo del Nuevo Testamento: tres días (Mt 12:40; 1 Co 15:4), tres testigos (Mt 18:16; 2 Co 13:1), tres tabernáculos en la Transfiguración (Mt 17:4). Todas las formas gramaticales (nominativo, genitivo, dativo; masculino, femenino, neutro) convergen en la evidencia interlingüística.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77870, 'spa', 'Temblar de temor', 'Estremecerse involuntariamente por miedo, reverencia o la conciencia abrumadora de una presencia poderosa. Marcos 5:33 y Lucas 8:47 muestran a la mujer con hemorragia temblando al confesarse ante Jesús, mientras Hechos 9:5 capta el terror de Saulo ante la voz del Cristo resucitado. En 2 Pedro 2:10 el término evoca el pavor que los seres angélicos legítimamente inspiran.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77871, 'spa', 'Alimentar, nutrir, sustentar', 'Proveer alimento o sustento a una persona o criatura. Es el sentido más amplio y frecuente, que abarca la alimentación divina de las aves (Mt 6:26; Lc 12:24), el justo que da de comer al hambriento (Mt 25:37), Tiro y Sidón dependiendo del territorio de Herodes para su abastecimiento (Hch 12:20) y la mujer sustentada en el desierto (Ap 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77874, 'spa', 'Amamantar, dar el pecho', 'Amamantar o dar de mamar a un infante. Se emplea en Lucas 23:29, donde Jesús camino al Calvario pronuncia una bienaventuranza sobre los pechos que nunca amamantaron. Este sentido especializado de carácter biológico se distingue del sustento general y se confirma por las traducciones árabes y suajili que emplean verbos específicos de lactancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77875, 'spa', 'Engordar, darse a excesos', 'Engordar o darse al exceso. Santiago 5:5 denuncia a los ricos que ''engordaron sus corazones en día de matanza'', usando τρέφω metafóricamente para el lujo desmedido que acumula juicio. Este sentido invierte las connotaciones positivas del sustento, transformando la provisión en autoindulgencia condenable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77877, 'spa', 'Criar, educar', 'Criar o educar a un niño durante un período prolongado. Lucas 4:16 describe a Jesús como habiendo sido ''criado'' en Nazaret, refiriéndose a años de formación durante la infancia y no a una sola comida. Este sentido enfatiza la formación y el entorno más que la mera ingesta, conectando el sustento físico con el desarrollo integral de la persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77879, 'spa', 'Correr físicamente', 'Correr físicamente: movimiento corporal veloz hacia o desde algo. Un espectador corre a llenar una esponja con vinagre (Mt 27:48; Mc 15:36); las mujeres corren de la tumba con gozo tembloroso (Mt 28:8); un endemoniado corre y se postra ante Jesús (Mc 5:6); el padre del pródigo corre a abrazarlo (Lc 15:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77881, 'spa', 'Esforzarse en una carrera', 'Esforzarse en una carrera: el uso metafórico tomado de la competición atlética griega. Pablo pregunta a los gálatas «¿quién os estorbó para no correr bien?» (Gál 5:7) y declara que no «corrió en vano» (Gál 2:2; Fil 2:16). Hebreos 12:1, con su imaginería de estadio y testigos, exhorta: «corramos con perseverancia».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77885, 'spa', 'Difundirse con rapidez', 'Difundirse con rapidez: dicho de un mensaje que avanza sin impedimento. Segunda Tesalonicenses 3:1 pide oración «para que la palabra del Señor corra», personificando el evangelio como un corredor. Esta única ocurrencia muestra la capacidad de la palabra para la extensión abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77894, 'spa', 'Treinta — número cardinal treinta, usado para el rendimiento agrícola (Mateo 13', 'Treinta — número cardinal treinta, usado para el rendimiento agrícola (Mateo 13:8, 23; Marcos 4:8, 20 — cosecha al treinta por uno), sumas monetarias (Mateo 26:15; 27:3, 9 — las treinta monedas de plata de la traición de Judas), edad (Lucas 3:23 — Jesús tenía unos treinta años al iniciar su ministerio), duración (Juan 5:5 — treinta y ocho años de enfermedad), y cómputo cronológico (Gálatas 3:17 — cuatrocientos treinta años). El precio de la traición de treinta monedas de plata carga con un profundo peso profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77897, 'spa', 'Senda del Señor', 'Las tres apariciones son la misma cita de Isaías 40:3 en Mateo 3:3, Marcos 1:3 y Lucas 3:4, introduciendo el ministerio de Juan el Bautista: «Enderezad sus sendas (τρίβους)». El paralelismo con «preparad el camino del Señor» muestra τρίβος como sinónimo de la ruta que el Señor recorrerá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77901, 'spa', 'Tres veces -- Adverbio numeral ''tres veces'', usado de manera prominente en la tr', 'Tres veces -- Adverbio numeral ''tres veces'', usado de manera prominente en la triple negación de Pedro (Mt 26:34, 75; Mr 14:30, 72; Lc 22:34, 61; Jn 13:38), también para los sufrimientos de Pablo (2 Co 11:25) y la visión de Pedro sobre los animales inmundos (Hch 10:16; 11:10). El español ''tres veces'', el francés ''trois fois'' y el alemán ''dreimal'' confirman un sentido adverbial único y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77904, 'spa', 'Tercero (ordinal)', 'El numeral ordinal estándar ''tercero'', que modifica sustantivos como ''día'', ''hora'' o ''ángel'', o aparece solo para identificar el tercer elemento de una secuencia. Jesús predice repetidamente que resucitará ''al tercer día'' (Mt 16:21; 17:23; 20:19). Este sentido también cubre la ''hora tercera'' de la crucifixión (Mc 15:25) y el tercer cielo mencionado por Pablo (2 Co 12:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77905, 'spa', 'Un tercio (fracción)', 'Uso sustantivado como neutro (τὸ τρίτον) para denotar la fracción ''un tercio'', describiendo destrucción parcial pero devastadora en los juicios de Apocalipsis. La tercera parte de la tierra es quemada (Ap 8:7), el mar se convierte en sangre (8:8), las naves son destruidas (8:9). El español ''tercera parte'' marca explícitamente la lectura fraccionaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77906, 'spa', 'Tercera vez (adverbial)', 'Uso adverbial (τὸ τρίτον o ἐκ τρίτου) con el significado de ''por tercera vez'' o ''una tercera vez'', marcando repeticiones significativas. Jesús ora por tercera vez en Getsemaní (Mt 26:44), a Pedro se le pregunta por tercera vez ''¿me amas?'' junto al mar de Tiberíades (Jn 21:17), y Pilato protesta la inocencia de Jesús ''por tercera vez'' (Lc 23:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77910, 'spa', 'Temblor reverente', 'Temblor o estremecimiento: sacudida física provocada por temor, reverencia o sumisión. Marcos 16:8 describe la reacción visceral de las mujeres ante el sepulcro vacío: el τρόμος las embargó junto con el ἔκθαμβος (espanto). Pablo adopta el binomio veterotestamentario ''temor y temblor'' (φόβος καὶ τρόμος) como expresión cuasi técnica para la postura reverente y humilde ante Dios o la autoridad espiritual (1 Corintios 2:3; 2 Corintios 7:15; Efesios 6:5; Filipenses 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77912, 'spa', 'Manera, modo -- El modo, forma o manera en que se realiza una acción o se desarr', 'Manera, modo -- El modo, forma o manera en que se realiza una acción o se desarrolla un acontecimiento. Aparece con mayor frecuencia en la construcción comparativa ὃν τρόπον (''de la manera que, así como''), estableciendo paralelos entre dos situaciones: el deseo de Jesús de reunir a Jerusalén (Mt 23:37; Lc 13:34), la forma de la ascensión y el retorno de Cristo (Hch 1:11), y la experiencia de la generación del éxodo (Hch 7:28). El español usa ''manera'' y ''modo'' de forma consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77919, 'spa', 'Alimento o nutrición consumida para sustentar el cuerpo; sustento en el sentido ', 'Alimento o nutrición consumida para sustentar el cuerpo; sustento en el sentido más amplio. Cubre la dieta específica de Juan el Bautista (Mt 3:4), las raciones diarias que un administrador del hogar reparte (Mt 24:45; Lc 12:42), y las comidas compartidas por la iglesia primitiva (Hch 2:46). Jesús lo usa en su enseñanza de que la vida trasciende el alimento (Mt 6:25; Lc 12:23), y Pablo insta a los compañeros del naufragio a tomar alimento (Hch 27:33-36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77923, 'spa', 'Compañero de Pablo', 'Hechos 20:4 lo menciona entre los compañeros de viaje de Pablo durante la colecta. Hechos 21:29 explica que judíos de Jerusalén lo habían visto con Pablo, asumiendo falsamente que este lo había llevado al templo. Segunda Timoteo 4:20 menciona que Pablo dejó a Trófimo enfermo en Mileto, revelando las dificultades reales de la vida misionera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77928, 'spa', 'Cosechar o vendimiar', 'Lucas 6:44 usa el término en la enseñanza de Jesús sobre reconocer a las personas por sus frutos: «¿Acaso se vendimian uvas de los espinos?». Apocalipsis 14:18-19 contiene dos usos en la escena dramática de la cosecha angélica: el ángel ordena recoger los racimos de la viña de la tierra, fusionando la imagen agrícola con el juicio divino final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77936, 'spa', 'Troas (ciudad)', 'Nombre propio geográfico de la ciudad portuaria de Alejandría Tróade en la costa noroeste de Asia Menor, punto de tránsito crucial entre las porciones asiática y europea del Imperio Romano. Aquí ocurrió la visión macedónica decisiva de Pablo (Hechos 16:8-10), y regresó en viajes posteriores (Hechos 20:5-6; 2 Corintios 2:12; 2 Timoteo 4:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77938, 'spa', 'Comer, masticar', 'Comer o masticar con énfasis en el acto físico y corporal de consumir alimento, un verbo más vívido y concreto que el común esthiō. En Juan 6:54-58, Jesús pasa deliberadamente de esthiō a trōgō al hablar de comer su carne, intensificando la impactante fisicalidad del discurso eucarístico. Mateo 24:38 lo emplea para la humanidad prediluviana absorta en su comer cotidiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77940, 'spa', 'Suceder, acontecer -- Suceder, ocurrir o acontecer por casualidad, un uso impers', 'Suceder, acontecer -- Suceder, ocurrir o acontecer por casualidad, un uso impersonal que expresa posibilidad o contingencia. Pablo escribe ''quizás de trigo o de algún otro grano'' (1 Co 15:37) y ''quizás me quede con vosotros'' (1 Co 16:6). El español ''quizás'' y ''acaso'' revelan claramente el vínculo etimológico con el azar y la fortuna que subyace en toda la familia léxica de esta palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77941, 'spa', 'Ordinario, común -- Ordinario, común o usual, la forma participial adjetiva que ', 'Ordinario, común -- Ordinario, común o usual, la forma participial adjetiva que típicamente aparece en construcciones de lítotes donde la negación produce énfasis. Los milagros a través de Pablo eran ''no comunes'' (οὐ τὰς τυχούσας, Hch 19:11), y los malteses mostraron ''no poca'' (οὐ τὴν τυχοῦσαν) amabilidad (Hch 28:2). El español ''comunes'' y el alemán ''gewöhnlich'' clarifican lo que el griego logra mediante la participialización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77942, 'spa', 'Obtener, alcanzar -- Obtener, alcanzar o recibir algo deseado o buscado', 'Obtener, alcanzar -- Obtener, alcanzar o recibir algo deseado o buscado. Pablo ''obtuvo ayuda de Dios'' (Hch 26:22), los elegidos se esfuerzan por ''alcanzar la salvación que es en Cristo Jesús'' (2 Ti 2:10), y los que son ''tenidos por dignos obtienen aquella era'' (Lc 20:35). El español usa ''alcanzar'' y ''obtener'', mientras que el francés ''obtenir'' y el alemán ''erlangen'' marcan consistentemente la adquisición deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77951, 'spa', 'Persona, comunidad o conducta presentada como ejemplo moral o patrón para la imi', 'Persona, comunidad o conducta presentada como ejemplo moral o patrón para la imitación. Este es el sentido dominante en el NT: los tesalonicenses se convirtieron en «ejemplo» para todos los creyentes (1 Tes 1:7), Pablo insta a imitar a quienes caminan según «el modelo que tenéis en nosotros» (Fil 3:17), y los ancianos deben ser «ejemplos para el rebaño» (1 Pe 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77953, 'spa', 'Patrón, plano o diseño', 'Patrón, plano o diseño: específicamente una plantilla divinamente revelada para la construcción. Hechos 7:44 recuerda que Dios dijo a Moisés que hiciera el tabernáculo «conforme al modelo» que le fue mostrado en el monte, y Hebreos 8:5 lo repite. El sentido enfatiza la réplica exacta de un original celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77954, 'spa', 'Marca, impresión o huella física dejada por contacto o un golpe', 'Marca, impresión o huella física dejada por contacto o un golpe: el significado etimológico raíz. Juan 20:25 lo usa dos veces para las marcas de los clavos en las manos de Jesús: Tomás dice que debe ver «la marca de los clavos» y poner su dedo «en la marca». Este es el sentido más concreto, preservando el origen de la palabra desde τύπτω (golpear).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77955, 'spa', 'La forma, patrón o formulación de algo escrito o enseñado', 'La forma, patrón o formulación de algo escrito o enseñado. Hechos 23:25 describe una carta «que tenía esta forma», y Romanos 6:17 habla del «modelo de enseñanza» al cual los creyentes fueron entregados. Este sentido tiende un puente entre la huella física y el modelo abstracto: una plantilla para contenido más que para construcción o conducta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77956, 'spa', 'Imagen o representación fabricada usada en el culto', 'Imagen o representación fabricada usada en el culto: una figura de ídolo. Hechos 7:43 condena a Israel por hacer «figuras» (τύπους) de dioses paganos para adorar. Este sentido extiende la «impresión» o «figura» física al ámbito de la representación religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77958, 'spa', 'Prefiguración tipológica', 'Prefiguración tipológica: una persona o acontecimiento en la historia de salvación anterior que presagia un cumplimiento posterior y mayor. Romanos 5:14 llama a Adán «tipo del que había de venir», estableciendo el concepto hermenéutico cristiano fundacional de la tipología. Este es el sentido de mayor carga teológica, donde la metáfora de la «huella» se convierte en patrón profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77960, 'spa', 'Golpear, azotar (activo) -- Golpear o azotar a alguien físicamente, abarcando go', 'Golpear, azotar (activo) -- Golpear o azotar a alguien físicamente, abarcando golpes con puños, varas o manos abiertas. Este sentido activo cubre todo el rango de uso neotestamentario: el abuso de Jesús durante su juicio (Mt 27:30; Mr 15:19), el mandamiento de poner la otra mejilla (Lc 6:29), el siervo malvado que golpea a los demás (Mt 24:49; Lc 12:45), y la extensión metafórica de Pablo sobre herir una conciencia débil (1 Co 8:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77967, 'spa', 'Ser golpeado (pasivo) -- Ser golpeado o azotado, la contraparte pasiva que apare', 'Ser golpeado (pasivo) -- Ser golpeado o azotado, la contraparte pasiva que aparece en Hch 23:3 donde Pablo dice al sumo sacerdote: ''¡Dios te va a golpear a ti, pared blanqueada!'', respondiendo tras haber sido golpeado en la boca. La voz pasiva pone en primer plano la experiencia de la víctima que recibe el golpe. Las traducciones reflejan el mismo vocabulario del sentido activo pero con morfología pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77971, 'spa', 'Tiro (ciudad fenicia) — Tiro, la antigua ciudad portuaria fenicia en la costa me', 'Tiro (ciudad fenicia) — Tiro, la antigua ciudad portuaria fenicia en la costa mediterránea, proverbialmente rica e históricamente sujeta a juicio profético (cf. Ezequiel 26-28; Isaías 23). En el NT, Jesús la usa como contraste en sus ayes: Tiro y Sidón se habrían arrepentido si hubieran visto sus milagros (Mateo 11:21-22; Lucas 10:13-14). Jesús ministra en su región, sanando a la hija de la mujer sirofenicia (Mateo 15:21; Marcos 7:24, 31). Pablo visita a los discípulos en Tiro durante su viaje a Jerusalén (Hechos 21:3, 7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77976, 'spa', 'Ciego (físico)', 'Ceguera física: la incapacidad de ver con los ojos. Es el sentido abrumadoramente dominante (49 de 50 apariciones), cubriendo cada relato evangélico de sanación y las referencias de Jesús a ''guías ciegos'' que carecen literalmente de vista. El español traduce consistentemente ''ciego'', sin variación a lo largo de estos pasajes (Mt 9:27-28; 11:5; 12:22; Jn 9:1-41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77980, 'spa', 'Ciego (espiritual)', 'Ceguera espiritual o metafórica: la incapacidad de percibir la realidad espiritual. Aparece una sola vez en Ap 3:17, donde Cristo le dice a la iglesia de Laodicea que es ''miserable, digna de compasión, pobre, ciega y desnuda''. La metáfora se apoya en el significado literal para exponer el autoengaño y la complacencia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77981, 'spa', 'Ceguera espiritual', 'Juan 12:40 cita Isaías 6:10 describiendo el endurecimiento judicial de Dios: «Les ha cegado los ojos». Segunda Corintios 4:4 atribuye la ceguera a Satanás: «el dios de este siglo cegó el entendimiento de los incrédulos». Primera Juan 2:11 muestra el odio como agente cegador: la oscuridad ciega los ojos de quien aborrece a su hermano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77982, 'spa', 'Envanecimiento soberbio', 'Primera Timoteo 3:6 advierte contra nombrar a un recién convertido como obispo, «no sea que, envaneciéndose, caiga en la condenación del diablo». Primera Timoteo 6:4 describe al falso maestro como «envanecido, sin saber nada», obsesionado con controversias. Segunda Timoteo 3:4 enumera los vicios de los últimos tiempos, incluyendo a quienes están «hinchados de orgullo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77985, 'spa', 'Nombre propio', 'Nombre propio de un cristiano de la provincia de Asia que sirvió como enviado y mensajero de confianza de Pablo. Entregó las cartas a los Efesios y a los Colosenses (Efesios 6:21; Colosenses 4:7), y Pablo consideró enviarlo a Tito en Creta (Tito 3:12) y después a Éfeso para relevar a Timoteo (2 Timoteo 4:12). En español se lo conoce como Tíquico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77988, 'spa', 'Vidrioso celestial', 'Las tres apariciones se encuentran en las descripciones visionarias del salón del trono celestial en Apocalipsis. Apocalipsis 4:6 presenta «un mar de vidrio (ὑαλίνη) semejante al cristal» ante el trono, creando una atmósfera de asombro. Apocalipsis 15:2 menciona dos veces el mar vidrioso, ahora «mezclado con fuego», donde los vencedores permanecen de pie con arpas en una escena de triunfo y adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77990, 'spa', 'Ultrajar con violencia', 'Tratar con violenta insolencia y abuso despectivo, abarcando tanto el maltrato físico como la afrenta verbal que vulnera el honor de una persona. En Mateo 22:6 los siervos del rey son tratados con ignominia, y en Lucas 18:32 Jesús profetiza que el Hijo del Hombre será burlado, ultrajado (ὑβρισθείς) y escupido. El término español ''ultrajados'' subraya el componente de indignación que lo diferencia de vocablos más leves.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77991, 'spa', 'Ultraje y daño', 'Hechos 27:10 y 27:21 aparecen en el relato del viaje marítimo de Pablo: él prevé que continuar acarrearía «daño» (ὕβρεως) a la carga y a las vidas, violencia provocada por los elementos. El segundo uso confirma su predicción tras la tormenta. En 2 Corintios 12:10, Pablo acepta gozosamente las «afrentas» (ὕβρεσιν) por amor a Cristo, enumerándolas entre las aflicciones que soporta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77993, 'spa', 'Sano, íntegro (doctrina) -- Metafóricamente sano o íntegro, dicho de la doctrina', 'Sano, íntegro (doctrina) -- Metafóricamente sano o íntegro, dicho de la doctrina, enseñanza, palabras o fe que son teológicamente correctas y espiritualmente saludables. Sello distintivo de las Epístolas Pastorales (1 Ti 1:10; 6:3; 2 Ti 1:13; 4:3; Tit 1:9, 13; 2:1-2), donde la metáfora médica implica que la falsa enseñanza es un contagio y la sana doctrina promueve la vitalidad espiritual. El español ''sana/sanas'' refleja este sentido con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77994, 'spa', 'Sano, saludable (físico) -- Literalmente sano, saludable o en buen estado físico', 'Sano, saludable (físico) -- Literalmente sano, saludable o en buen estado físico, describiendo la condición corporal de una persona. Jesús lo usa en su proverbio del médico: ''los sanos no tienen necesidad de médico'' (Lc 5:31). El siervo del centurión es hallado ὑγιαίνοντα, ''con buena salud'' (Lc 7:10), y el padre se regocija de que su hijo pródigo ha regresado ὑγιαίνοντα, ''sano y salvo'' (Lc 15:27). El deseo de Juan por la salud física de Gayo (3 Jn 2) confirma este sentido literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77999, 'spa', 'Sano, bien (salud física) -- Describe a una persona restaurada a plena salud fís', 'Sano, bien (salud física) -- Describe a una persona restaurada a plena salud física, libre de enfermedad o discapacidad. Casi todas las apariciones neotestamentarias se agrupan en narrativas de sanación, especialmente Jn 5, donde la palabra aparece seis veces en torno a un milagro junto al estanque de Betesda. Las glosas interlingüísticas la traducen consistentemente como plenitud corporal: español ''sano/sana'', francés ''en bonne santé'', alemán ''gesund''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78001, 'spa', 'Sano, íntegro (doctrina/palabras) -- Transferencia metafórica de la salud corpor', 'Sano, íntegro (doctrina/palabras) -- Transferencia metafórica de la salud corporal a la integridad doctrinal, presente exclusivamente en las Epístolas Pastorales. Pablo habla de ''palabras sanas'' (1 Ti 6:3), ''sana doctrina'' (Tit 2:1) y ''palabra sana e irreprochable'' (Tit 2:8). El mismo español ''sana'' sirve para ambos sentidos, mostrando cuán naturalmente la metáfora viaja entre idiomas. Así como un cuerpo sano funciona sin corrupción, así también la enseñanza íntegra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78003, 'spa', 'Tinaja de agua', 'Juan 2:6-7 contiene dos de las tres apariciones: seis tinajas de piedra (ὑδρίας) dispuestas para los ritos de purificación judía en Caná, que Jesús manda llenar de agua antes de transformarla en vino. Eran vasijas grandes de entre 75 y 115 litros cada una. Juan 4:28 describe a la mujer samaritana dejando su cántaro (ὑδρίαν) junto al pozo cuando corre a contarle a su aldea sobre Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78006, 'spa', 'Agua', 'La sustancia agua en todas sus apariciones neotestamentarias: cuerpos naturales (mares, ríos, pozos), agua para beber, ritos de purificación y bautismo. Jesús contrasta el agua física con el ''agua viva'' (Jn 4:10-14), y Juan el Bautista distingue el bautismo en agua del bautismo en el Espíritu (Mt 3:11). La traducción universal como ''agua'' confirma un único sentido léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78011, 'spa', 'Lluvia divina', 'Lluvia o aguacero abundante, presentado siempre bajo la soberanía divina en el Nuevo Testamento. Dios concede lluvias y estaciones fructíferas como testimonio ante las naciones (Hch 14:17), y el ciclo de Elías se recuerda en Stg 5:18. No hay polisemia: cada uso apunta al mismo fenómeno gobernado por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78012, 'spa', 'Adopción filial', 'Concepto teológico-jurídico de ser constituido hijo en la familia de Dios, con plenos derechos de herencia. Pablo lo aplica a la realidad presente —el Espíritu capacita el clamor «Abba, Padre» (Ro 8:15; Gá 4:5)— y a la esperanza escatológica de la redención corporal (Ro 8:23). Designa también un privilegio de Israel (Ro 9:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78013, 'spa', 'hijo, descendiente', 'Sustantivo griego que designa un descendiente varón, un hijo o alguien que pertenece a un grupo o se caracteriza por una cualidad determinada. El uso literal comprende hijos biológicos (Mt 1:21). El título cristológico ὁ υἱὸς τοῦ θεοῦ (''el Hijo de Dios'', Mt 3:17; 16:16) y el apocalíptico ὁ υἱὸς τοῦ ἀνθρώπου (''el Hijo del Hombre'', Mt 8:20) dominan el panorama teológico. El modismo semítico ''hijos de...'' expresa pertenencia categorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78022, 'spa', 'Vuestro, de vosotros — pronombre o adjetivo posesivo enfático de segunda persona', 'Vuestro, de vosotros — pronombre o adjetivo posesivo enfático de segunda persona del plural que significa ''vuestro'' o ''de vosotros'', usado con énfasis para atribuir posesión, asociación o responsabilidad a los interlocutores. Jesús lo emplea para contrastar su situación con la de los discípulos (Juan 7:6, ''vuestro tiempo''; Juan 8:17, ''vuestra ley''; Juan 15:20, ''vuestra palabra/persecución''), para prometer la posesión del reino (Lucas 6:20, ''vuestro es el reino''), y para distinguir lo propio de lo ajeno (Lucas 16:12). Pablo lo usa para expresar pertenencia mutua y asuntos espirituales (1 Cor 15:31; 16:17; Gál 6:13). Las traducciones existentes ''de vosotros'', ''vuestra'', ''vuestro'' reflejan adecuadamente este posesivo enfático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78027, 'spa', 'Cantar himnos de alabanza', 'Entonar alabanzas o cantar un himno en adoración a Dios, sea en liturgia comunitaria o en devoción personal. Mateo 26:30 y Marcos 14:26 describen a Jesús y los discípulos cantando tras la cena pascual, probablemente los salmos del Hallel. Hechos 16:25 muestra a Pablo y Silas cantando himnos en prisión a medianoche, y Hebreos 2:12 pone el verbo en labios del Mesías mismo a través del Salmo 22:22.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78029, 'spa', 'Ir, dirigirse', 'Movimiento o desplazamiento general: ''ir, dirigirse, ponerse en camino''. Sentido dominante en 78 apariciones, usado en imperativos donde Jesús envía a personas con misiones o encargos (Mt 5:24, ''Ve, reconcíliate primero''; Mt 8:4, ''Ve, muéstrate al sacerdote''). El español ''id/voy'' lo traduce directamente como movimiento simple hacia un destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78041, 'spa', 'Irse, partir', 'Partida o retirada deliberada: ''irse, marcharse'', con énfasis en alejarse más que en llegar. Se encuentra en pasajes cargados de emoción: la pregunta de Jesús, ''¿También vosotros queréis iros?'' (Jn 6:67), y la nota de que muchos ''se iban'' a creer en Jesús (Jn 12:11). El español ''iros/se iban'' marca este movimiento como separativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78045, 'spa', 'Obediencia -- Sumisión voluntaria a un mandato con autoridad, especialmente a Di', 'Obediencia -- Sumisión voluntaria a un mandato con autoridad, especialmente a Dios, al evangelio o a Cristo. La frase paulina ''obediencia de la fe'' (Ro 1:5; 16:26) describe la respuesta apropiada al evangelio, mientras que Ro 5:19 contrasta la παρακοή de Adán con la ὑπακοή de Cristo. En 2 Co 10:5-6 la palabra se extiende a la sumisión intelectual. El español ''obediencia'', el francés ''obéissance'' y el alemán ''Gehorsam'' confirman uniformemente un núcleo semántico único y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78047, 'spa', 'Obedecer, cumplir o someterse a los mandatos de una autoridad', 'Obedecer, cumplir o someterse a los mandatos de una autoridad. Se usa para los elementos naturales que obedecen a Jesús (Mt 8:27; Mc 4:41; Lc 8:25), los espíritus malignos que se someten a su autoridad (Mc 1:27) y los creyentes que obedecen el evangelio, a sus amos o a sus padres. Cubre 20 de las 21 apariciones en los Evangelios y las Epístolas, expresando una sumisión voluntaria y completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78057, 'spa', 'Abrir una puerta o responder a un llamado o golpe — el sentido etimológico origi', 'Abrir una puerta o responder a un llamado o golpe — el sentido etimológico original de ὑπακούω como ''escuchar desde abajo'' o ''atender un llamado''. En Hechos 12:13, la sirvienta Rode va ὑπακοῦσαι (''a abrir'') la puerta cuando Pedro llama. Solo 1 aparición en el NT, un eco encantador del sentido clásico de la palabra como atención y respuesta a una solicitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78060, 'spa', 'Encontrarse, salir al encuentro — ir al encuentro de alguien cara a cara, salir ', 'Encontrarse, salir al encuentro — ir al encuentro de alguien cara a cara, salir a recibir o encontrarse con una persona en saludo, súplica o circunstancia casual. Abarca la mayoría de las apariciones: los endemoniados gadarenos encuentran a Jesús al salir de los sepulcros (Mt 8:28; Mc 5:2; Lc 8:27), las mujeres encuentran al Cristo resucitado en el camino (Mt 28:9), y el siervo sale al encuentro del grupo del oficial con noticias de la curación (Jn 4:51). Las traducciones en distintos idiomas coinciden uniformemente en el sentido de encuentro amistoso o neutral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78064, 'spa', 'Oponerse, confrontar — salir al encuentro en sentido hostil o adversarial, confr', 'Oponerse, confrontar — salir al encuentro en sentido hostil o adversarial, confrontar u oponerse a una fuerza militar. En Lucas 14:31, un rey delibera si puede enfrentarse a otro rey que marcha contra él con el doble de tropas. La evidencia multilingüe acentúa esta distinción: en hindi ''saamna karne ko'' (confrontar/hacer frente), en coreano ''맞서기를'' (oponerse), y en español ''salir al encuentro'' (con sentido de desafío), todos señalan el matiz de confrontación bélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78065, 'spa', 'Recepción solemne', 'Mateo 8:34 muestra a toda la ciudad saliendo «al encuentro» (εἰς ὑπάντησιν) de Jesús tras sanar a los endemoniados, aunque le pidieron que se fuera. Mateo 25:1 describe a las diez vírgenes saliendo «al encuentro» del novio en una recepción nupcial formal. Juan 12:13 presenta a la multitud de Jerusalén saliendo «al encuentro» de Jesús con ramos de palma en lo que celebramos como Domingo de Ramos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78067, 'spa', 'Ser, existir', 'Uso primario en el NT: ser, existir o hallarse en cierto estado o condición. Funciona como alternativa elevada a εἰμί, señalando a menudo algo ya establecido o inherentemente verdadero del sujeto. Lucas lo emplea extensamente para describir condiciones existentes (Lc 7:25, ''los que visten ropas finas''; Lc 16:14, los fariseos que ''eran amantes del dinero'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78068, 'spa', 'Posesiones, bienes', 'El participio neutro plural sustantivado τὰ ὑπάρχοντα, que significa posesiones, pertenencias o bienes. Este uso es especialmente prominente en la enseñanza de Jesús sobre la riqueza y el discipulado: ''vende tus posesiones'' (Mt 19:21), el siervo fiel puesto sobre todos los bienes de su señor (Mt 24:47) y la parábola de los talentos (Mt 25:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78094, 'spa', 'Poseer activamente', 'Única aparición en Hch 4:37 donde la forma participial describe a Bernabé como ''poseedor'' de un campo antes de venderlo. Aunque está estrechamente relacionado con el sentido 2 (bienes materiales), la construcción participial activa aquí enfatiza el acto de tener o poseer más que las posesiones en sí. El español ''poseyendo'' capta esta cualidad verbal y procesual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78098, 'spa', 'en favor de, por', 'Sentido benefactivo y sustitutorio dominante: obrar en favor de, en interés de o en lugar de alguien. Es la preposición de la teología expiatoria — ''el pan que yo daré ὑπέρ la vida del mundo'' (Jn 6:51), ''esta es mi sangre derramada ὑπέρ vosotros'' (Lc 22:20). El español ''por'', el francés ''pour'' y el alemán ''für'' convergen en este significado de agencia en beneficio de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78100, 'spa', 'acerca de, sobre', 'Referencia temática: acerca de, con respecto a un asunto. Juan el Bautista habla ὑπέρ Jesús — ''acerca de'' él (Jn 1:30); Pablo escribe ὑπέρ Tito — ''sobre'' su compañero (2 Co 8:23). Este uso se superpone con περί, pero conlleva un tono más implicado, como si quien habla tuviera un interés personal en el tema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78101, 'spa', 'sobre, por encima de', 'Superioridad espacial o jerárquica: sobre, por encima de. Un discípulo no está ὑπέρ su maestro (Mt 10:24); quien ama a su padre o madre ὑπέρ Jesús no es digno de él (Mt 10:37). Lc 6:40 extiende la idea al alumno plenamente formado que llega a ser ''como'' su maestro, sin elevarse por encima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78102, 'spa', 'más allá de, más que', 'Exceso comparativo o superación: indica algo que rebasa un criterio o un límite. El caso acusativo activa este desplazamiento de lo espacial a lo comparativo — una luz ''más allá'' del resplandor del sol (Hch 26:13), no pensar ''más allá'' de lo que está escrito (1 Co 4:6). El español ''más allá de'' y ''más que'' captan la noción de desbordamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78105, 'spa', 'sobremanera, abundantísimamente', 'Intensificador adverbial que expresa grado extremo, frecuente en compuestos paulinos: ὑπερεκπερισσοῦ (infinitamente más, Ef 3:20), ὑπερλίαν (superapóstoles, 2 Co 11:5), ὑπερβαλλόντως (sobremanera, 2 Co 11:23). El español lo recoge con vigor: ''muchísimo más abundantemente'', ''sobreabundantemente''. Estas formaciones compuestas son distintivamente paulinas y expresan una teología de la sobreabundancia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78116, 'spa', 'Autoexaltación orgullosa', 'La voz media reflexiva enfatiza la autoexaltación, elevarse por encima de los límites debidos por orgullo. En 2 Corintios 12:7 advierte contra la soberbia espiritual derivada de las revelaciones, mientras que 2 Tesalonicenses 2:4 retrata la arrogancia escatológica de oponerse a Dios. El sentido reflexivo consistente en las traducciones —«se exalta», «s''élever»— destaca la naturaleza autodirigida de esta elevación presuntuosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78118, 'spa', 'Supremacía trascendente', 'Efesios 1:21 declara a Cristo sentado «muy por encima» de todo gobierno, autoridad, poder y señorío. Efesios 4:10 describe su ascensión «por encima» de todos los cielos para llenarlo todo. Hebreos 9:5 menciona los querubines de gloria cubriendo el propiciatorio. En cada caso, el término señala posición suprema y soberanía absoluta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78122, 'spa', 'Sobrepasar incomparablemente', 'Sobrepasar o exceder toda comparación, usado por Pablo exclusivamente en forma participial para señalar realidades de grado extraordinario. En 2 Co 3:10 la gloria que sobrepasa (ὑπερβάλλον) del nuevo pacto reduce a nada la del antiguo; en Ef 1:19 y 2:7 describe la inconmensurable grandeza del poder y la gracia de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78123, 'spa', 'Grado superlativo, exceso', 'Un grado superlativo o extraordinario, un exceso que sobrepasa toda medida normal. Usado casi exclusivamente por Pablo en la frase adverbial καθ'' ὑπερβολήν (sobremanera, en extremo) o en construcciones genitivas que expresan cualidad superlativa. En Romanos 7:13 el pecado llega a ser «sobremanera pecaminoso»; en 2 Corintios 1:8 la aflicción de Pablo lo apremió «excesivamente, más allá de sus fuerzas»; en 2 Corintios 4:17 habla de un eterno peso de gloria incomparable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78134, 'spa', 'Superioridad y preeminencia', 'Ocupar una posición por encima de otros, ya sea en autoridad, valor personal o excelencia incomparable. Pablo instruye la sumisión a las autoridades «superiores» (ὑπερεχούσαις) en Ro 13:1, insta a estimar a los demás como superiores en Fil 2:3, y declara que conocer a Cristo sobrepasa (ὑπερέχον) todo en Fil 3:8. La paz de Dios sobrepasa todo entendimiento (Fil 4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78136, 'spa', 'Soberbia arrogante', 'Arrogante y altivo, describe a quien se exalta sobre los demás con orgullo despectivo que provoca oposición divina. En Lc 1:51 María proclama que Dios dispersa a los soberbios (ὑπερηφάνους); en Ro 1:30 y 2 Ti 3:2 aparece en catálogos de vicios. Pr 3:34, citado en Stg 4:6 y 1 P 5:5, subraya que Dios resiste a los soberbios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78145, 'spa', 'Aposento alto', 'Habitación en el piso superior de una casa, usada para reuniones, oración o velatorio de difuntos antes del entierro. Hechos 1:13 identifica el célebre aposento alto donde los apóstoles aguardaron Pentecostés. Hechos 9:37,39 ubican el cuerpo de Tabita en dicha sala en Jope, mientras que Hechos 20:8 sitúa el sermón nocturno de Pablo en una sala superior iluminada con lámparas en Troas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78147, 'spa', 'Obediencia voluntaria', 'Hechos 7:39 describe a la generación del desierto como no dispuesta a ser «obediente» a Moisés, rechazando su liderazgo designado por Dios. 2 Corintios 2:9 revela el propósito de Pablo: comprobar si los corintios son «obedientes» en todo. Filipenses 2:8 describe a Cristo haciéndose «obediente» hasta la muerte de cruz, modelo supremo de sumisión voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78148, 'spa', 'Servicio ministerial', 'Hechos 13:36 resume la vida de David: «sirvió» al propósito de Dios en su generación, cumpliendo su llamado ministerial. Hechos 20:34 recuerda cómo las manos de Pablo «sirvieron» para cubrir sus necesidades y las de sus compañeros. Hechos 24:23 describe la orden de Félix de permitir que los amigos de Pablo le «asistieran», proveyendo ayuda práctica durante su custodia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78149, 'spa', 'Oficial, guardia del templo', 'Oficial, guardia del templo: oficial, guardia o asistente judicial que sirve bajo la autoridad de los sumos sacerdotes, el Sanedrín o un magistrado. Son la policía del templo que arresta, detiene y ejecuta órdenes durante los relatos del juicio. En Jn 7:32 y 7:45-46, los ὑπηρέται son enviados a prender a Jesús pero regresan con las manos vacías. En Mt 5:25, el ὑπηρέτης es el alguacil que encarcela al deudor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78151, 'spa', 'Servidor, ayudante, ministro', 'Servidor, ayudante, ministro: servidor personal, asistente o ministro que atiende a alguien o sirve a una causa. Lc 1:2 habla de testigos oculares que se hicieron ὑπηρέται de la palabra; el asistente de la sinagoga en Lc 4:20 entrega el rollo a Jesús; Juan Marcos actúa como ὑπηρέτης de Pablo y Bernabé (Hch 13:5); y Pablo es designado ὑπηρέτης y testigo de Cristo (Hch 26:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78156, 'spa', 'Sueño', 'Sueño físico natural o sopor, abarcando el descanso ordinario y sus extensiones figuradas hacia la modorra espiritual y el eufemismo de la muerte. José despierta del hypnos tras el mensaje angélico (Mateo 1:24); los discípulos están abrumados de sueño en la Transfiguración (Lucas 9:32); Jesús distingue el sueño de Lázaro de un hypnos ordinario (Juan 11:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78159, 'spa', 'por (agente)', 'Marca de agente con caso genitivo: ''por'' una persona, fuerza o agente divino. Con 171 ocurrencias, es el sentido abrumadoramente dominante, presente en construcciones pasivas a lo largo del Nuevo Testamento. La fórmula mateana de cumplimiento ''lo dicho por el Señor por medio del profeta'' (Mt 1:22; 2:15) es paradigmática. El español ''por'' lo traduce de modo constante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78160, 'spa', 'debajo de, bajo', 'Posición espacial con caso acusativo: ''debajo de, bajo.'' Con 51 ocurrencias, denota ubicación física bajo un objeto o subordinación metafórica bajo una autoridad. No se pone una lámpara ''debajo de'' un almud (Mt 5:15); el centurión se declara hombre ''bajo'' autoridad (Mt 8:9); Jesús anhela reunir a los hijos de Jerusalén ''bajo'' sus alas (Mt 23:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78165, 'spa', 'hacia (temporal)', 'Aproximación temporal: ''hacia, alrededor de (un momento).'' Una sola ocurrencia en Hch 5:21, donde el sanedrín se reúne ὑπὸ τὸν ὄρθρον, ''hacia el amanecer.'' Este uso de proximidad temporal, aunque raro en el Nuevo Testamento, tiene precedente clásico (ὑπὸ νύκτα, ''al caer la noche''). El español ''hacia'' confirma una lectura temporal, ni espacial ni agentiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78168, 'spa', 'Ejemplo, modelo, patrón', 'Un modelo, ejemplo o patrón presentado ante alguien para su imitación o como advertencia. Jesús dice a los discípulos ''os he dado ejemplo'' tras lavarles los pies (John 13:15); Santiago señala a los profetas como ejemplos de paciencia (Jas 5:10); y el autor de Hebreos advierte contra caer ''en el mismo ejemplo de desobediencia'' (Heb 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78169, 'spa', 'Copia, representación', 'Una copia, bosquejo o representación imperfecta de una realidad superior y celestial. Se usa exclusivamente en Hebreos para referirse al tabernáculo terrenal como imagen derivada del verdadero santuario en el cielo (Heb 8:5; 9:23). La forma terrenal sirve y prefigura al original, no al revés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78172, 'spa', 'Mostrar, demostrar', 'Mostrar, demostrar o señalar algo, haciendo visible lo que antes estaba oculto o era desconocido. Se usa cuando Jesús declara ''os mostraré a quién temer'' (Luke 12:5), cuando Pablo recuerda cómo el Señor le ''mostró'' los sufrimientos venideros (Acts 9:16), y cuando la enseñanza se ilustra con ejemplos (Luke 6:47; Acts 20:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78173, 'spa', 'Advertir, amonestar', 'Advertir o prevenir a alguien, señalándole un peligro inminente o un juicio divino como amonestación cautelar. Tanto Juan el Bautista como Jesús preguntan a las multitudes: ''¿Quién os advirtió que huyerais de la ira venidera?'' (Matt 3:7; Luke 3:7). El paso de un mostrar neutro a una advertencia urgente queda confirmado por el suajili ''aliwaonya'' (les advirtió).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78175, 'spa', 'Acoger con hospitalidad', 'Dar la bienvenida a alguien en la propia casa como huésped, brindando hospitalidad personal. Lucas 10:38 muestra a Marta recibiendo a Jesús; Lucas 19:6 presenta a Zaqueo acogiéndolo con alegría. Hechos 17:7 describe a Jasón albergando a Pablo y Silas con riesgo legal personal, y Santiago 2:25 evoca la acogida de Rahab a los espías como un acto de fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78176, 'spa', 'Calzar sandalias', 'Marcos 6:9 registra a Jesús instruyendo a los Doce a «llevar sandalias» pero sin túnica extra: viajar ligeros con lo básico. Hechos 12:8 muestra al ángel ordenando a Pedro en prisión «átate las sandalias», preparándose para partir. Efesios 6:15 emplea el participio «calzados» los pies con la disposición del evangelio de paz, dentro de la metáfora de la armadura espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78177, 'spa', 'Sandalia, calzado — calzado básico de cuero atado al pie, que porta un peso simb', 'Sandalia, calzado — calzado básico de cuero atado al pie, que porta un peso simbólico en tres ámbitos: humildad servil (Juan el Bautista indigno de llevar o desatar las sandalias de Jesús, Mt 3:11; Mc 1:7; Hch 13:25), dependencia misionera (los Doce enviados sin sandalias de repuesto, Mt 10:10; Lc 10:4; 22:35), y encuentro sagrado (Moisés quitándose las sandalias en tierra santa, Hch 7:33). Al hijo pródigo se le calzan sandalias como señal de restauración y dignidad filial (Lc 15:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78183, 'spa', 'Debajo de, bajo — preposición espacial que significa ''debajo de, bajo, por debaj', 'Debajo de, bajo — preposición espacial que significa ''debajo de, bajo, por debajo'', indicando una posición inferior o subordinada respecto a algo. Se usa en la cita del salmo mesiánico sobre los enemigos puestos ''debajo de sus pies'' (Mt 22:44; Mc 12:36; Heb 2:8, citando el Salmo 110:1), en el argumento de la mujer sirofenicia sobre los perros ''debajo de la mesa'' (Mc 7:28), en la instrucción de sacudir el polvo de ''debajo de vuestros pies'' (Mc 6:11), la lámpara que nadie pone ''debajo de la cama'' (Lc 8:16), y las almas que claman desde ''debajo del altar'' (Ap 6:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78185, 'spa', 'Hipocresía, fingimiento', 'El acto o cualidad de aparentar creencias, virtudes o sentimientos que en realidad no se poseen — un vicio moral enraizado en la metáfora teatral de representar un papel. Jesús lo usa para condenar la pretensión religiosa en Matt 23:28 y Mark 12:15; Lucas 12:1 lo llama ''la levadura de los fariseos''; Pablo confronta la hipocresía colectiva en Antioquía (Gal 2:13); y 1 Tim 4:2 advierte sobre enseñanzas demoníacas transmitidas con hipocresía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78189, 'spa', 'Hipócrita, farsante', 'Hipócrita, farsante: farsante religioso que practica la piedad exterior sin sinceridad interior, originalmente un término teatral para un actor que hablaba a través de una máscara. Jesús lo emplea como su epíteto principal para los escribas y fariseos: los que oran ostentosamente (Mt 6:2, 5), desfiguran sus rostros al ayunar (Mt 6:16) y cuelan el mosquito mientras se tragan el camello (Mt 23:13-29). La séptuple ''¡Ay de vosotros, hipócritas!'' constituye la denuncia más concentrada de los Evangelios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78194, 'spa', 'Recibir o acoger', 'Tomar o recibir a alguien, ya sea de manera física o con hospitalidad. En la Ascensión, una nube lo ''recibió'' (Hch 1:9) apartándolo de la vista de los discípulos, y 3 Juan 1:8 exhorta a los creyentes a ''acoger'' (ὑπολαμβάνειν) a los misioneros itinerantes para ser colaboradores en la verdad. El sentido apunta a la acción concreta de recibir o sostener a alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78198, 'spa', 'Soportar, perseverar bajo adversidad', 'Soportar, perseverar bajo adversidad: soportar con paciencia o perseverar bajo dificultad, prueba u oposición sin ceder (15 ocurrencias). Este es el sentido teológicamente denso: ''el que persevere hasta el fin será salvo'' (Mt 10:22; 24:13; Mc 13:13). Hebreos presenta a Jesús como ejemplo supremo, quien ''soportó la cruz'' (12:2). Santiago señala la firmeza de Job (5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78208, 'spa', 'Quedarse, permanecer', 'Quedarse, permanecer: permanecer en un lugar después de que otros se han marchado — el sentido espacial literal del compuesto (2 ocurrencias). En Lc 2:43, el Jesús de doce años ''se quedó'' en Jerusalén cuando sus padres partieron, y en Hch 17:14 Silas y Timoteo ''se quedaron'' en Berea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78213, 'spa', 'Recordar, hacer memoria', 'Recordar activamente a alguien algo, devolver un asunto a la atención de otra persona. Jesús promete que el Espíritu Santo les ''recordará todo lo que les he dicho'' (Jn 14:26) — aquí el Espíritu es el agente del recuerdo. Pablo emplea el verbo para instrucción pastoral: recuérdales estas cosas (2 Ti 2:14), recuérdales que se sujeten a los gobernantes (Tit 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78216, 'spa', 'Acordarse, recordar (pasivo)', 'Ser llevado a recordar, tener algo traído a la memoria (pasivo/intransitivo). En Lc 22:61, tras el canto del gallo, Pedro ''se acordó'' (ὑπεμνήσθη) de la palabra del Señor — el énfasis recae en la experiencia de un recuerdo súbito e involuntario, más que en un agente externo que provoque el recuerdo. El aoristo pasivo griego subraya lo repentino del momento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78220, 'spa', 'Recordatorio pastoral', '2 Timoteo 1:5 habla de la fe sincera de Timoteo, trayendo a «remembranza» la fe que primero habitó en su abuela Loida y su madre Eunice. 2 Pedro 1:13 explica el propósito de Pedro: «avivaros con recordatorio» para mantener las verdades activas. 2 Pedro 3:1 identifica esta como su segunda carta escrita a modo de recordatorio para despertar un entendimiento sincero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78221, 'spa', 'perseverancia, resistencia paciente', 'perseverancia, resistencia paciente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78224, 'spa', 'Suponer o sospechar', 'En Hechos 13:25, Juan el Bautista pregunta: «¿Quién suponéis (ὑπονοεῖτε) que soy?», desafiando las suposiciones de la multitud. En Hechos 25:18, Festo explica que los acusadores no presentaron los cargos que él «suponía» (ὑπενόουν). En Hechos 27:27, los marineros «sospechaban» (ὑπενόουν) que se acercaban a tierra. En cada caso, se trata de un juicio provisional ante información limitada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78228, 'spa', 'Escabel, estrado', 'Un escabel — literalmente un soporte bajo para los pies, pero en el NT empleado casi enteramente como metáfora de la soberanía divina y la sujeción de los enemigos. La cita dominante es el Salmo 110:1 (''hasta que ponga a tus enemigos por estrado de tus pies''), citado en Lc 20:43, Hch 2:35, He 1:13 y He 10:13 para establecer el reinado exaltado de Cristo. En Hch 7:49, citando Is 66:1, la tierra misma es el estrado de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78232, 'spa', 'Esencia o sustancia', 'La esencia subyacente, la naturaleza sustancial o el ser mismo de algo. En Heb 1:3 el Hijo es ''la imagen exacta de su ὑπόστασις'', es decir, del ser esencial de Dios, pasaje que resultó fundamental para la teología trinitaria nicena. El término señala la realidad ontológica objetiva que sustenta lo aparente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78233, 'spa', 'Retraerse por temor', 'Echarse atrás, rehuir o abstenerse de algo por miedo o presión social, fallando en mantenerse firme en la convicción. Pablo insiste dos veces en que nunca se retrajo de declarar la verdad (Hch 20:20, 27), mientras que Gálatas 2:12 muestra a Pedro retirándose de la comunión con los gentiles bajo presión del partido de la circuncisión. Hebreos 10:38 presenta el retroceso como lo opuesto a vivir por fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78235, 'spa', 'regresar a un lugar', 'regresar a un lugar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78249, 'spa', 'volverse atrás, retroceder', 'volverse atrás, retroceder');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78252, 'spa', 'Sujeción a la autoridad', 'El acto o disposición de colocarse bajo autoridad, ya sea voluntariamente en respuesta al evangelio (2 Co 9:13), rechazada cuando comprometería la verdad evangélica (Gá 2:5), o practicada en contextos de aprendizaje y del hogar (1 Ti 2:11; 3:4). El término describe una posición ordenada y relacional dentro de una estructura de autoridad, no una obediencia pasiva o forzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78253, 'spa', 'someterse, sujetarse', 'someterse, sujetarse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78255, 'spa', 'sujetar, subordinar (activo causativo)', 'sujetar, subordinar (activo causativo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78260, 'spa', 'ser sometido (pasivo divino)', 'ser sometido (pasivo divino)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78285, 'spa', 'Soportar con paciencia', 'En 1 Corintios 10:13, se asegura a los creyentes que ninguna tentación es excesiva y que Dios provee salida para que puedan «soportarla» (ὑποφέρειν). En 2 Timoteo 3:11, Pablo celebra las persecuciones que «soportó» (ὑπήνεγκα), demostrando la liberación divina. En 1 Pedro 2:19 se elogia a quien sobrelleva injusticias por conciencia ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78290, 'spa', 'Quedarse corto ante un estándar', 'Quedarse corto ante un estándar: sentido comparativo o aspiracional: no alcanzar un estándar o medida. Pablo lo usa dos veces al compararse con los ''superapóstoles'' (2 Co 11:5; 12:11). En He 4:1 el autor advierte que nadie parezca haberse quedado atrás de entrar al reposo de Dios, y He 12:15 previene contra quedarse corto de la gracia de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78291, 'spa', 'Carecer, ser deficiente', 'Carecer, ser deficiente: el sentido central de carecer o estar sin algo necesario. En Mt 19:20 y Mc 10:21, el joven rico pregunta qué le falta todavía; en 1 Co 1:7 Pablo asegura a los corintios que no carecen de ningún don espiritual. La evidencia apunta consistentemente a una deficiencia objetiva de algo necesario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78296, 'spa', 'Padecer necesidad, estar en escasez', 'Padecer necesidad, estar en escasez: el sentido experiencial de sufrir carencia o padecer necesidad. La persona no simplemente carece de un artículo, sino que vive en condición de privación. El hijo pródigo en Lc 15:14 ''comenzó a padecer necesidad'' tras derrochar todo, y Pablo en 2 Co 11:9 recuerda sus propias penurias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78301, 'spa', 'Acabarse, agotarse', 'Acabarse, agotarse: sentido referido a una provisión: un recurso que se agota o se acaba. Usado solo en Jn 2:3, donde el vino de la fiesta de bodas se acabó. El contexto — una provisión finita consumida por completo — distingue este sentido de la experiencia humana de carencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78305, 'spa', 'Carencia, deficiencia', 'Estado de carencia, deficiencia o necesidad: el déficit concreto entre lo que se posee y lo que se requiere. Puede tratarse de pobreza material, como cuando la viuda echa todo lo que tiene de su necesidad (Lc 21:4), o de ausencia relacional, como cuando la presencia de los corintios suple lo que faltaba (1 Co 16:17; Fil 2:30). Pablo también lo usa para el equilibrio recíproco entre abundancia y necesidad (2 Co 8:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78312, 'spa', 'Después, luego — adverbio temporal que indica una posición posterior o conclusiv', 'Después, luego — adverbio temporal que indica una posición posterior o conclusiva en una secuencia. Jesús ayuna y ''después'' tiene hambre (Mt 4:2). En las parábolas marca el clímax narrativo: un hijo ''después'' se arrepiente (Mt 21:29), el dueño envía a su hijo ''por último'' (21:37), y las vírgenes insensatas llegan ''después'' ante una puerta cerrada (Mt 25:11). Frecuentemente conlleva un matiz de finalidad u oportunidad perdida: lo que llega tarde puede llegar demasiado tarde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78316, 'spa', 'Alto, elevado (físico/espacial) -- Físicamente elevado, alto o espacialmente enc', 'Alto, elevado (físico/espacial) -- Físicamente elevado, alto o espacialmente encumbrado. Se usa predominantemente para montes en momentos narrativos clave: el monte de la tentación (Mt 4:8; Lc 4:5), el monte de la Transfiguración (Mt 17:1; Mr 9:2), y Dios elevando a Israel durante la estancia en Egipto (Hch 13:17). El español ''alto'' y ''alturas'', el francés ''haut'' y el alemán ''hoch'' convergen en el significado espacial directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78317, 'spa', 'Orgulloso, altivo (figurado/moral) -- Figuradamente alto en el sentido de orgull', 'Orgulloso, altivo (figurado/moral) -- Figuradamente alto en el sentido de orgulloso, altivo o moralmente arrogante. Pablo advierte a los creyentes romanos que no sean ''altivos'' (Ro 11:20) y que no aspiren a ''cosas altas'' (Ro 12:16, τὰ ὑψηλά). Jesús declara en Lc 16:15 que lo ''exaltado'' entre los hombres es abominación ante Dios. El español ''altivas cosas'' y ''altivamente'' captura el matiz moral ausente en el sentido meramente espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78323, 'spa', 'Altísimo — título divino que designa a Dios en su soberanía suprema y trascenden', 'Altísimo — título divino que designa a Dios en su soberanía suprema y trascendencia. Usado como sustantivo, frecuentemente con artículo, nombra a Dios en contextos de declaración profética, anuncio angélico e incluso reconocimiento demoníaco. Lucas lo emplea con frecuencia: el niño será ''Hijo del Altísimo'' (1:32), el Espíritu Santo como ''poder del Altísimo'' (1:35), Juan el Bautista como ''profeta del Altísimo'' (1:76).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78324, 'spa', 'Lo más alto — superlativo espacial o doxológico que designa los cielos más altos', 'Lo más alto — superlativo espacial o doxológico que designa los cielos más altos, el ámbito supremo de gloria o el grado máximo de alabanza. Aparece exclusivamente en la aclamación litúrgica ἐν τοῖς ὑψίστοις: ''¡Hosanna en las alturas!'' en la entrada triunfal (Mateo 21:9, Marcos 11:10, Lucas 19:38) y ''Gloria a Dios en las alturas'' en el nacimiento de Cristo (Lucas 2:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78327, 'spa', 'Altura, lugar elevado', 'Altura literal, un lugar alto o elevado, a menudo referido al ámbito celestial. Lucas habla del amanecer que visita ''desde lo alto'' (Luke 1:78) y del poder que viene ''desde lo alto'' (Luke 24:49). Pablo incluye ''la altura'' entre las dimensiones cósmicas del amor de Cristo (Eph 3:18) y cita el Salmo sobre ascender ''a lo alto'' (Eph 4:8). Apocalipsis mide la altura de la ciudad (Rev 21:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78329, 'spa', 'Exaltación, posición honrosa', 'Exaltación metafórica, posición elevada u honor conferido a alguien de condición terrenal humilde. Santiago insta al hermano de baja condición a ''gloriarse en su exaltación'' (Jas 1:9), donde la palabra denota dignidad y honor divino más que elevación física. El español ''exaltación'' y el hindi ''unche pad'' (posición alta) marcan el paso de lo espacial a lo social o espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78331, 'spa', 'Exaltar en estatus u honor', 'Exaltar en estatus u honor: exaltar en estatus, honor o poder — el sentido más frecuente en el NT. Dios exalta a los humildes y derriba a los soberbios (Lc 1:52); se pregunta a Capernaúm si será exaltada hasta el cielo (Mt 11:23); Dios exaltó a Jesús a su diestra (Hch 2:33; 5:31; Fil 2:9). Trece ocurrencias usan ὑψόω para la elevación divina o social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78334, 'spa', 'Levantar físicamente', 'Levantar físicamente: levantar física o cuasi-físicamente, especialmente del Hijo del Hombre siendo levantado en la cruz. Jn 3:14 establece la tipología con la serpiente de bronce; Jn 8:28 y 12:32-34 la desarrollan, donde ''ser levantado de la tierra'' significa tanto crucifixión como ascensión. El doble sentido joánico — la vergüenza transformada en gloria — hace de este sentido algo teológicamente único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78335, 'spa', 'Exaltarse a sí mismo', 'Exaltarse a sí mismo: el sentido reflexivo, siempre con advertencia. ''El que se exalta será humillado'' aparece en Mt 23:12, Lc 14:11 y 18:14. Solo dos ocurrencias llevan este sentido autodirigido, pero el patrón de inversión — exaltarse a sí mismo, ser humillado — es una de las enseñanzas más memorables de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78347, 'spa', 'Comer, alimentarse', 'Comer o consumir alimento, usado para el acto literal de comer en todas las formas gramaticales: indicativo, subjuntivo, imperativo, infinitivo, futuro y participial. Las 93 apariciones abarcan comidas ordinarias, alimentaciones milagrosas (Mt 14:16, 20; Mc 6:37), disputas sobre alimentos lícitos (Mt 12:4; Mc 7:3-5), el ayuno y su ruptura, y el banquete escatológico (Lc 22:30; Ap 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78375, 'spa', 'aparecer, hacerse visible', 'aparecer, hacerse visible');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78376, 'spa', 'parecer, dar apariencia de', 'parecer, dar apariencia de');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78381, 'spa', 'brillar, dar luz', 'brillar, dar luz');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78400, 'spa', 'Manifiesto, evidente, conocido', 'Manifiesto, evidente, conocido: claramente visible, públicamente conocido, evidentemente perceptible al entendimiento. Este es el sentido dominante en dieciséis ocurrencias, usado de secretos que serán revelados (Mc 4:22; Lc 8:17), de la identidad de Jesús haciéndose ampliamente conocida (Mc 3:12; 6:14) y de realidades espirituales que son evidentes por sí mismas (Gá 5:19; 1 Jn 3:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78401, 'spa', 'Exterior, externo', 'Exterior, externo: exterior, externo, relativo a lo que es visible en la superficie en contraste con lo interior u oculto. Este uso especializado aparece en Ro 2:28, donde Pablo argumenta que ''el que es judío ἐν τῷ φανερῷ'' — exteriormente, en la circuncisión visible de la carne — no es el verdadero judío. El contraste con la dimensión oculta (ἐν τῷ κρυπτῷ) le da a φανερός un matiz espacial, casi físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78409, 'spa', 'Aparecer, manifestarse (personas)', 'La manifestación o aparición personal de Cristo u otras personas, especialmente la encarnación, las apariciones postpascuales y la parusía futura. Juan emplea este sentido repetidamente: Jesús «fue manifestado» a Israel (Jn 1:31), apareció a los discípulos junto al mar de Tiberias (Jn 21:14) y se mostró tras resucitar (Mc 16:12, 14). El sujeto es una persona que se hace visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78410, 'spa', 'Dar a conocer (activo)', 'La revelación activa e intencional por parte de un agente personal. Jesús «manifestó su gloria» mediante señales (Jn 2:11), «reveló» el nombre del Padre a sus discípulos (Jn 17:6) y busca «darse a conocer» al mundo (Jn 7:4). Las formas «manifesté/manifestó» en español preservan la agencia en primera y tercera persona. Este sentido subraya la iniciativa deliberada del revelador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78413, 'spa', 'Ser revelado, descubierto', 'La revelación pasiva de cosas: obras, pecados, verdades o misterios son sacados a la luz. Marcos 4:22 promete que nada hay oculto que no haya de ser manifestado. Pablo afirma que la justicia de Dios ha sido revelada (Ro 3:21). El sujeto es impersonal: lo que estaba escondido queda ahora expuesto. El español «fue manifestado/manifestada» reproduce fielmente esta pasividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78440, 'spa', 'Abierta o claramente', 'En Marcos 1:45, el leproso sanado difunde la noticia de tal modo que Jesús ya no podía entrar «abiertamente» (φανερῶς) en ninguna ciudad. En Juan 7:10, Jesús sube a la fiesta «no públicamente» (οὐ φανερῶς), evitando deliberadamente la visibilidad. En Hechos 10:3, Cornelio ve un ángel «claramente» (φανερῶς) en una visión, subrayando la nitidez de la revelación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78448, 'spa', 'Rey de Egipto', 'El título real del rey de Egipto, usado en el Nuevo Testamento exclusivamente en referencia al Faraón del periodo del Éxodo. Esteban relata cómo Faraón exaltó a José (Hch 7:10), cómo la familia de José fue presentada ante Faraón (Hch 7:13), y cómo la hija de Faraón adoptó a Moisés (Hch 7:21). Pablo lo invoca como paradigma del endurecimiento y la soberanía divina (Ro 9:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78449, 'spa', 'Nombre propio: Fares', 'En Mateo 1:3 aparece dos veces al listar la descendencia de Judá: «Judá engendró a Fares (Φαρές) y a Zera de Tamar, y Fares engendró a Hesrón». Lucas 3:33 traza el linaje de Jesús hasta «Hesrón, hijo de Fares (Φαρές)». Incluir a Fares y a Tamar en la genealogía mesiánica subraya cómo Dios obra a través de circunstancias humanamente imprevistas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78450, 'spa', 'fariseo', 'Miembro de los fariseos, movimiento religioso-político judío que insistía en la estricta observancia de la Torá, la autoridad de la tradición oral junto a la Escritura escrita y la escrupulosa evitación de la contaminación ritual. En los Evangelios aparecen como interlocutores y adversarios frecuentes de Jesús en cuestiones de ley sabática, pureza y autoridad (Mt 12:2; 23:13-36), aunque figuras notables como Nicodemo (Jn 3:1) y Pablo (Fil 3:5) matizan el cuadro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78460, 'spa', 'Hechicero u ocultista', 'Apocalipsis 9:21 enumera cuatro pecados de los que la humanidad no se arrepintió tras la sexta trompeta: homicidio, «hechicerías» (φαρμάκων), inmoralidad sexual y hurto. Apocalipsis 21:8 cataloga a los excluidos de la nueva Jerusalén, incluyendo a los «hechiceros» (φαρμακοῖς) junto a cobardes, incrédulos, homicidas e idólatras. Apocalipsis 22:15 reafirma esta exclusión en la descripción final de la ciudad santa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78462, 'spa', 'Afirmar con énfasis', 'En Hechos 24:9 los judíos «afirmaban» (φάσκοντες) que los cargos contra Pablo eran ciertos, sumándose a la acusación. En Hechos 25:19 Festo explica que Pablo «aseveraba» (ἔφασκεν) que Jesús estaba vivo. En Romanos 1:22 se condena a quienes «pretenden» (φάσκοντες) ser sabios pero se vuelven necios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78463, 'spa', 'Pesebre o comedero', 'Un comedero o pesebre para ganado, empleado en el NT tanto como la cuna improvisada donde María acostó al recién nacido Jesús (Lc 2:7, 12, 16) como el utensilio cotidiano del que comen bueyes y asnos (Lc 13:15). La evidencia multilingue es unánime: el español pesebre, el francés crèche y el alemán Krippe apuntan a un receptáculo concreto para alimentar animales, subrayando la humildad de la encarnación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78464, 'spa', 'Malo, vil, perverso', 'Moralmente malo, vil o perverso — describe acciones, prácticas o carácter de baja calidad moral, en contraste con lo bueno (ἀγαθός) o noble (καλός). John 3:20 advierte que quienes practican lo malo (ὁ τὰ φαῦλα πράσσων) aborrecen la luz; John 5:29 contrasta la resurrección de vida con la resurrección de juicio para quienes practicaron τὰ φαῦλα. Pablo recoge esta polaridad moral en Rom 9:11 y 2 Cor 5:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78468, 'spa', 'Resplandor celeste', 'Mateo 24:29 y Marcos 13:24 presentan la profecía apocalíptica paralela: tras la tribulación, «el sol se oscurecerá y la luna no dará su resplandor» (φέγγος). Lucas 11:33 usa el término de modo distinto: nadie enciende una lámpara para ocultarla, sino para que los que entren vean «la luz» (φέγγος), cumpliendo así su propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78469, 'spa', 'Perdonar, abstenerse de dañar', 'Perdonar, abstenerse de dañar. Contenerse de infligir daño, castigo o severidad. Se usa de Dios no escatimando a su propio Hijo (Ro 8:32) en paralelo deliberado con la Aqedá (Gn 22 LXX), de Dios no perdonando las ramas naturales del olivo (Ro 11:21) ni al mundo antiguo (2 P 2:4-5), de Pablo absteniéndose de disciplina severa hacia los corintios (2 Co 1:23; 13:2), y de lobos salvajes que no muestran misericordia al rebaño (Hch 20:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78479, 'spa', 'Traer o buscar', 'Traer, buscar o conducir hacia un destino; es el sentido dominante con 41 apariciones. Abarca traer un paralítico a Jesús (Mc 2:3), llevar el agua convertida en vino (Jn 2:8) y la orden «traédmelos aquí» (Mt 14:18; 17:17). El español «trae/traed» y los imperativos resultan especialmente frecuentes en este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78485, 'spa', 'Dar fruto, producir', 'Dar fruto o producir resultados, con 9 apariciones concentradas en la metáfora joánica de la vid (Jn 12:24; 15:2-8) y la parábola del sembrador en Marcos (Mc 4:8). El español «lleva fruto» emplea «llevar» en una colocación agrícola fija. La expresión «llevar mucho fruto» se convierte en exigencia central del discipulado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78491, 'spa', 'Cargar, transportar', 'Cargar o transportar un objeto o persona físicamente, con 9 apariciones donde el énfasis recae en sostener la carga más que en la dirección del traslado. Incluye cargar la cruz (Lc 23:26) y llevar especias al sepulcro (Lc 24:1). A diferencia del sentido 1, aquí se destaca el peso y la duración del esfuerzo, no el destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78492, 'spa', 'Impulsar, arrastrar', 'Ser arrastrado o impulsado por una fuerza externa: el viento, el Espíritu o las circunstancias. La nave arrastrada por la tormenta (Hch 27:15, 17), el viento impetuoso de Pentecostés (Hch 2:2) y los profetas «llevados por el Espíritu Santo» (2 P 1:21). Hebreos 6:1 extiende la imagen: «dejémonos llevar a la madurez», evocando un impulso divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78498, 'spa', 'Soportar, tolerar', 'Soportar o tolerar algo difícil, con solo 2 apariciones en el margen semántico del verbo. En Romanos 9:22 Dios «soportó con paciencia» vasos de ira; en Hebreos 12:20 los israelitas «no podían soportar» la orden del Sinaí. El español «soportar» recurre a un verbo dedicado a la resistencia, alejándose del campo del transporte físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78517, 'spa', 'El sentido dominante (28 veces)', 'El sentido dominante (28 veces): huir o escapar de un peligro, persecución o amenaza. Pasajes clave incluyen la huida a Egipto (Mt 2:13), huir de ciudad en ciudad ante la persecución (Mt 10:23), el desafío de Jesús sobre escapar del juicio de la Gehena (Mt 23:33) y los pastores que huyen cuando viene el lobo (Jn 10:12-13). Expresa la urgencia de una partida inmediata ante el peligro inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78524, 'spa', 'Sentido resultativo (1 vez en Heb 11', 'Sentido resultativo (1 vez en Heb 11:34): escapar o librarse con éxito, con énfasis en el resultado logrado más que en el acto de huir. En el gran capítulo de la fe, los héroes de la antigüedad «escaparon del filo de la espada». El enfoque recae en la liberación consumada, no en la huida emprendida. Una distinción sutil pero real dentro del campo semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78528, 'spa', 'Félix (nombre propio)', 'Nombre propio que identifica al procurador romano de Judea, Antonio Félix, quien gobernó durante el encarcelamiento de Pablo en Cesarea. El nombre latino significa «feliz» o «afortunado». La narrativa de Lucas lo presenta como un político calculador: mantiene a Pablo preso durante dos años esperando un soborno y lo deja encadenado para congraciarse con los judíos (Hch 24:26-27). Las nueve apariciones se concentran en Hechos 23-25.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78530, 'spa', 'Decir, declarar', 'Decir, hablar o declarar; verbo introductorio del discurso directo que enmarca citas en el Nuevo Testamento. Se emplea casi exclusivamente en tercera persona (φησί, ἔφη) como marcador de cita en intercambios narrativos ágiles: Jesús ante el Sanedrín (Mt 26:34, 61), el diálogo de Pilato (Mt 27:11) y las defensas de Pablo (Hch 26:24-25). El español «dijo» lo traduce uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78538, 'spa', 'Festo — nombre propio que identifica a Porcio Festo, procurador romano de Judea ', 'Festo — nombre propio que identifica a Porcio Festo, procurador romano de Judea que sucedió a Antonio Félix (Hechos 24:27). Las 13 ocurrencias aparecen en Hechos 24-26, cubriendo su asunción del cargo (Hechos 25:1), la audiencia del caso de Pablo (Hechos 25:4, 9, 12), su consulta con el rey Agripa (Hechos 25:13-14, 22-24) y su exclamación asombrada durante la defensa de Pablo (Hechos 26:24-25, 32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78539, 'spa', 'Llegar, alcanzar', 'Llegar a, alcanzar o arribar a un lugar, estado o persona — enfatizando el logro más que la prioridad. Este sentido dominante en el NT aparece cuando Jesús declara que el reino de Dios ''ha llegado'' a sus oyentes (Mt 12:28; Lc 11:20), cuando Pablo pregunta si Israel ''alcanzó'' la ley de justicia (Ro 9:31), y cuando afirma haber ''llegado'' a los corintios con el evangelio (2 Co 10:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78544, 'spa', 'Preceder, anticiparse', 'Preceder, ir delante o llegar antes que otros — conservando el sentido clásico de adelantarse o anticipar. En 1 Ts 4:15, Pablo asegura a los creyentes que ''nosotros los que estemos vivos de ninguna manera precederemos a los que durmieron'', empleando φθάνω en su registro competitivo original. El énfasis contextual en el orden de la resurrección hace inequívoca la prioridad temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78545, 'spa', 'Perecedero, corruptible', 'Describe algo susceptible a la corrupción, el deterioro o la destrucción: la fragilidad inherente y transitoriedad de la existencia material y terrenal. En 1 Pedro 1:18 se recuerda a los creyentes que fueron rescatados no con cosas perecederas como plata u oro, sino con la sangre preciosa de Cristo. Las traducciones en múltiples idiomas (español corruptible, alemán vergänglich, francés périssable) confirman uniformemente este sentido único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78548, 'spa', 'Emitir habla articulada', 'Hechos 4:18 relata cómo el Sanedrín ordenó a Pedro y Juan no «hablar» (φθέγγεσθαι) ni enseñar en el nombre de Jesús. Segunda Pedro 2:16 describe a la burra de Balaam que «habló» (φθεγξάμενον) con voz humana reprendiendo la locura del profeta. Segunda Pedro 2:18 condena a los falsos maestros que «pronuncian» (φθεγγόμενοι) palabras grandilocuentes y vacías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78549, 'spa', 'Destruir, arruinar', 'Destruir o llevar a la ruina como acto de juicio o consecuencia. En 1 Corintios 3:17 la advertencia es tajante: Dios «destruirá» al que profane su templo. En 2 Pedro 2:12 y Judas 10, los falsos maestros «perecen» en su propia corrupción como animales irracionales. Este sentido subraya una ruina irreversible, no un deterioro gradual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78550, 'spa', 'Corromper moralmente', 'Corromper moralmente, contaminar o causar el deterioro del carácter, la mente o la conducta. Pablo lo emplea para la seducción moral (2 Co 11:3, donde la mente de Eva fue corrompida por la astucia de la serpiente), el efecto corrosivo de las malas compañías (1 Co 15:33) y la decadencia progresiva del viejo hombre (Ef 4:22). En Apocalipsis 19:2, Babilonia «corrompió» la tierra con su inmoralidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78561, 'spa', 'Envidia, malquerencia', 'El vicio de la envidia o la hostilidad celosa: un resentimiento provocado por la buena fortuna, el estatus o las posesiones ajenas. En el NT se retrata consistentemente como destructivo y pecaminoso. Los principales sacerdotes entregan a Jesús a Pilato movidos por φθόνος (Mt 27:18; Mr 15:10), revelando la envidia como motivo de la mayor injusticia de la historia. Pablo lo cataloga entre las obras de la carne (Gá 5:21) y lo asocia con disputas y sospechas maliciosas (1 Ti 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78565, 'spa', 'Destrucción, ruina', 'Destrucción activa y ruina provocada por la depravación moral o el juicio divino. En 2 Pedro predomina este sentido: los falsos maestros son «esclavos de la corrupción» (2:19) que serán «destruidos en su propia destrucción» (2:12), con verbo y sustantivo juntos para énfasis demoledor. Los creyentes deben escapar de «la corrupción que hay en el mundo por la concupiscencia» (1:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78566, 'spa', 'Corrupción, deterioro', 'El estado o proceso de corrupción, deterioro y caducidad: la condición natural del cuerpo mortal y la creación caída. Pablo lo empareja con la resurrección: el cuerpo se siembra en φθορά pero resucita en ἀφθαρσία (1 Co 15:42). La creación gime bajo «esclavitud de la corrupción» esperando liberación (Ro 8:21). Quien siembra para la carne cosecha corrupción (Gá 6:8).');